const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={name:'',avatar:'🦊',motion:false,progress:{},sessions:0},storageOK=true;
try{const saved=JSON.parse(localStorage.getItem('mattesteg-v1')||'null');if(saved&&typeof saved==='object'){state={...state,...saved,progress:saved.progress||{}};if(!['🦊','🐻','🐸'].includes(state.avatar))state.avatar='🦊';state.name=String(state.name||'').slice(0,24);}}catch{storageOK=false;}
let page='home',session=null;
function save(){try{localStorage.setItem('mattesteg-v1',JSON.stringify(state));}catch{storageOK=false;}}
function applyProfile(){document.body.classList.toggle('reduced',!!state.motion);$('#profile').textContent=`${state.avatar} ${state.name||'Velg din figur'}`;}
function stat(id){return state.progress[id]||{independent:0,supported:0,variants:[],last:null};}
function label(id){const p=stat(id);return p.independent>=6&&p.variants.length>=2?'Godt på vei':p.independent||p.supported?'Du er i gang':'Klar til å utforske';}
function recommend(){return MathEngine.topics.find(t=>stat(t.id).independent<6)||MathEngine.topics[0];}
function navigate(next){page=next;if(window.speechSynthesis)window.speechSynthesis.cancel();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='home')home();if(page==='library')library();if(page==='parent')parent();window.scrollTo({top:0,behavior:'instant'});}
function home(){const next=recommend();const total=MathEngine.topics.reduce((s,t)=>s+stat(t.id).independent,0);$('#app').innerHTML=`<section class="hero"><div class="hero-copy"><span class="eyebrow">DIN LÆRINGSSTI · DITT TEMPO</span><h1>${state.name?`Hei, ${esc(state.name)}!<br>`:''}Store oppdagelser.<br>Små mattesteg.</h1><p>Her er det lov å prøve, undre seg og prøve igjen. Vi finner veien sammen, ett lite steg av gangen.</p><button class="primary" data-start="${next.id}">Ta neste steg <span aria-hidden="true">→</span></button> <span class="note">ca. 5 minutter</span></div><div class="hero-art" aria-hidden="true"><div class="number-tile">3</div><div class="number-tile two">7</div><span class="spark">✳</span><span class="mascot">${state.avatar}</span><div class="art-line"><span>0</span><span>1</span><span>2</span><span>3</span><span>4</span><span>5</span></div></div></section><section class="stats" aria-label="Din fremgang"><div class="stat"><span class="stat-icon">↗</span><div><b>${total} selvstendige svar</b><small>Små tegn på fremgang</small></div></div><div class="stat"><span class="stat-icon">✦</span><div><b>${state.sessions} økter</b><small>Hvert forsøk teller</small></div></div><div class="stat"><span class="stat-icon">♡</span><div><b>Ingen hastverk</b><small>Du bestemmer tempoet</small></div></div></section><div class="section-title"><h2>Hva vil du utforske?</h2><p>Du kan alltid velge et annet tema.</p></div><section class="cards">${MathEngine.topics.map(t=>`<article class="card ${t.id===next.id?'featured':''}"><div class="card-top"><span class="topic-icon" aria-hidden="true">${t.icon}</span><span class="badge">${t.id===next.id?'Forslag til neste steg':label(t.id)}</span></div><h3>${t.title}</h3><p>${t.desc}</p><button data-start="${t.id}">Utforsk temaet <span style="float:right">→</span></button></article>`).join('')}</section><section class="strip"><span class="topic-icon">⌁</span><div><strong>Usikker på hvor du skal begynne?</strong><p>Prøv seks små oppgaver. Vi foreslår et sted å starte.</p></div><button class="secondary" id="map">Finn mitt startpunkt →</button></section>${!storageOK?'<p class="note">Nettleseren tillater ikke lagring. Du kan øve, men fremgangen blir ikke bevart.</p>':''}`;bindStarts();$('#map').onclick=()=>start('mapping');}
function bindStarts(){document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>start(b.dataset.start));}
function start(id){session={id,index:0,correct:0,helped:0,results:[],attempts:0,assisted:false,easy:false,done:false};newQuestion();}
function newQuestion(){const id=session.id==='mapping'?MathEngine.topics[session.index].id:session.id;session.q=MathEngine.question(id,session.index,session.easy);session.attempts=0;session.assisted=false;session.done=false;exercise();}
function dots(n,gold=false){return `<span class="dotgroup">${Array.from({length:n},()=>`<span class="dot ${gold?'gold':''}"></span>`).join('')}</span>`;}
function visual(v){if(v.type==='dots')return dots(v.a);if(v.type==='line')return `<div class="line">${Array.from({length:v.max+1},(_,i)=>i===v.a?'<b>?</b>':`<span>${i}</span>`).join('')}</div>`;if(v.type==='frame')return `<div class="tenframe">${Array.from({length:10},(_,i)=>`<span class="cell ${i<v.a?'filled':''}"></span>`).join('')}</div>`;if(v.type==='place')return `${Array.from({length:v.a},()=>'<span style="background:#66886b;color:white;border-radius:6px;padding:5px 10px;font-size:20px">10</span>').join('')} ${dots(v.b,true)}`;if(v.type==='add')return `${dots(v.a)} <span>+</span> ${dots(v.b,true)}`;return `<span class="dotgroup">${Array.from({length:v.a},(_,i)=>`<span class="dot" style="${i<v.b?'opacity:.25;border:2px dashed #285e51;background:transparent':''}"></span>`).join('')}</span><span style="font-size:14px">${v.b} tas bort</span>`;}
function exercise(){page='exercise';document.querySelectorAll('nav button').forEach(b=>b.classList.remove('active'));const q=session.q,t=MathEngine.topics.find(t=>t.id===q.id);$('#app').innerHTML=`<section class="exercise"><div class="exercise-head"><button class="secondary" id="leave">← Ta en pause</button><span class="note">${session.id==='mapping'?'Finn ditt startpunkt':t.title} · ${session.index+1} av 6</span></div><div class="progress" aria-label="Oppgave ${session.index+1} av 6"><span style="width:${session.index/6*100}%"></span></div><div class="question-box"><span class="eyebrow">${session.id==='mapping'?'PRØV DET DU KAN':'ET LITE STEG OM GANGEN'}</span><h1 id="question">${q.prompt}</h1><p class="note">${session.id==='mapping'?'Dette er et forslag til startpunkt, ikke en karakter.':'Tenk i ditt eget tempo. Hjelp er alltid tilgjengelig.'}</p><div id="visual">${q.id==='quantity'||(q.id==='line'&&q.variant===0)?`<div class="visual">${visual(q.visual)}</div>`:''}</div><div class="answers">${q.options.map(n=>`<button class="answer" data-answer="${n}">${n}</button>`).join('')}</div><div id="feedback" aria-live="polite"></div><div id="helper"></div><div class="help-actions"><button class="secondary" id="picture">Vis med et bilde</button><button class="secondary" id="hint">Gi meg et hint</button><button class="secondary" id="read">♫ Les opp</button>${session.id!=='mapping'?'<button class="secondary" id="easier">Prøv et enklere eksempel</button>':''}</div></div></section>`;$('#leave').onclick=()=>navigate('home');document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));$('#picture').onclick=()=>{if(!session.done)session.assisted=true;$('#visual').innerHTML=`<div class="visual" role="img" aria-label="${esc(q.explain)}">${visual(q.visual)}</div>`;};$('#hint').onclick=()=>{if(!session.done)session.assisted=true;$('#helper').innerHTML=`<div class="helper">${t.hint}</div>`;};$('#read').onclick=()=>{if('speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(q.prompt);u.lang='nb-NO';u.rate=.85;speechSynthesis.speak(u);}else $('#helper').innerHTML='<div class="helper">Opplesning er ikke tilgjengelig i denne nettleseren.</div>';};if($('#easier'))$('#easier').onclick=()=>{session.easy=true;newQuestion();$('#helper').innerHTML='<div class="helper">Vi prøver med mindre tall. Det er en fin måte å undersøke ideen på.</div>';};}
function answer(value){if(session.done)return;const q=session.q;session.attempts++;if(value!==q.answer){session.assisted=true;$('#feedback').innerHTML=`<div class="feedback">Det ble ikke helt riktig. ${MathEngine.topics.find(t=>t.id===q.id).hint} Prøv igjen, eller se forklaringen.</div><button class="secondary" id="explain">Vis forklaringen og gå videre</button>`;$('#explain').onclick=()=>complete(false);return;}complete(true);}
function complete(correct){session.done=true;const independent=correct&&!session.assisted&&session.attempts===1;session.results.push({id:session.q.id,independent,correct});if(independent)session.correct++;else session.helped++;const p=stat(session.q.id);if(correct){if(independent){p.independent++;p.variants=[...new Set([...p.variants,session.q.variant])];}else p.supported++;p.last=new Date().toISOString();state.progress[session.q.id]=p;save();}document.querySelectorAll('[data-answer]').forEach(b=>b.disabled=true);if($('#easier'))$('#easier').disabled=true;$('#feedback').innerHTML=`<div class="feedback ${correct?'success':''}">${correct?`${state.name?esc(state.name)+', ':''}det stemmer! `:'La oss se på det sammen. '}${session.q.explain}${correct&&!independent?' Du fant frem med hjelp. Neste gang kan du prøve selv.':''}</div><button class="primary" id="next">${session.index===5?'Se hvordan det gikk':'Neste lille steg →'}</button>`;$('#next').onclick=()=>{session.index++;if(session.index===6)finish();else newQuestion();};}
function finish(){state.sessions++;save();let suggestion=session.id==='mapping'?MathEngine.topics.find(t=>session.results.find(r=>r.id===t.id&&!r.independent))||MathEngine.topics[0]:MathEngine.topics.find(t=>t.id===session.id);$('#app').innerHTML=`<section class="result"><span class="mascot" aria-hidden="true">${state.avatar}</span><span class="eyebrow">DU HAR TATT DEG TID TIL Å ØVE</span><h1>Seks små steg er tatt!</h1><p>${session.correct} oppgaver løst uten hjelp. ${session.helped} oppgaver utforsket med hjelp eller forklaring.</p><div class="article"><h2>${session.id==='mapping'?'Et sted å starte':'Hva nå?'}</h2><p>${session.id==='mapping'?`Vi foreslår «${suggestion.title}». Seks oppgaver gir bare et første inntrykk. Du kan velge et annet tema.`:'Prøv temaet igjen en annen dag. Nye tall og ulike spørsmål hjelper oss å se hva som sitter.'}</p></div><button class="primary" data-start="${suggestion.id}">Øv på ${suggestion.title.toLowerCase()}</button><button class="secondary" id="back">Til læringsstien</button></section>`;bindStarts();$('#back').onclick=()=>navigate('home');}
const articles=[
 {title:'Tall og mengder',text:'Tallet forteller hvor mange ting det er. Fem knapper er fortsatt fem når du flytter dem rundt.',example:'Legg frem fem skjeer. Spre dem utover, og skyv dem sammen igjen. Antallet endrer seg ikke.',parent:'Be barnet lage en mengde som passer til tallet 5. Spør: Hvordan vet du at det er fem?',shortcut:'Flytt hver ting til en ny haug når du teller. Da blir hver ting telt én gang.'},
 {title:'Tallinja',text:'Tallinja viser tall i rekkefølge. Med like store steg øker tallet med én hver gang du går én plass mot høyre.',example:'Tegn tallene 0 til 10 på papir. Sett en brikke på 3 og flytt den to steg mot høyre. Nå står den på 5.',parent:'Spør hva som kommer før og etter et tall. La barnet peke og forklare.',shortcut:'Ved pluss kan du telle steg mot høyre. Ved minus kan du telle steg mot venstre.'},
 {title:'Plassverdi: enere og tiere',text:'I 24 står 2 på tierplassen og betyr 20. Tallet 4 står på enerplassen og betyr fire. Til sammen blir det 24.',example:'Samle sugerør i bunter på ti. To bunter og fire løse sugerør er 24 sugerør.',parent:'Spør: Hva betyr 2 i 24? Hva skjer hvis vi bytter plass på sifrene?',shortcut:'Ti enere kan byttes mot én tier. Mengden er den samme.'},
 {title:'Tiervenner',text:'Tiervenner er to tall som blir ti når vi legger dem sammen. 7 og 3 er tiervenner fordi 7 + 3 = 10.',example:'En eggekartong med ti plasser har sju egg. Tre plasser er tomme.',parent:'Tegn ti ruter og fyll noen av dem. Spør hvor mange som mangler.',shortcut:'Når du vet at 7 + 3 = 10, vet du også at 3 + 7 = 10.'},
 {title:'Addisjon: å legge sammen',text:'Når vi legger sammen, finner vi hvor mange det blir totalt. 4 + 3 betyr fire og tre til.',example:'Du har fire epler og får tre til. Nå har du sju.',parent:'La barnet vise regnestykket med ting, tegning eller tallinje. Spør hvordan barnet fant svaret.',shortcut:'Fyll opp til ti: 8 + 5 kan deles i 8 + 2 + 3. Det blir 10 + 3 = 13. Vi deler opp femmeren uten å endre mengden.'},
 {title:'Subtraksjon: å trekke fra',text:'Minus kan bety å ta bort, men også å finne forskjellen mellom to mengder. 8 − 3 = 5.',example:'Du har åtte epler og gir bort tre. Fem er igjen. Hvis én har åtte og en annen tre, er forskjellen også fem.',parent:'Spør både hva som er igjen og hvor mange flere den ene har. Vis med to rader av ting.',shortcut:'Sjekk minus med pluss: Hvis 8 − 3 = 5, skal 5 + 3 bli 8.'}
];
function library(){ $('#app').innerHTML='<span class="eyebrow">FOR SMÅ OG STORE UNDRENDE HODER</span><h1>En annen måte å forstå det på.</h1><p>Finn en forklaring, et hverdagseksempel eller et tips til å øve sammen.</p><label for="search">Søk etter et tema eller ord</label><input class="search" id="search" type="search" placeholder="Prøv tiervenner, pluss eller tallinje …"><div id="articles"></div>';function filter(){const term=$('#search').value.trim().toLocaleLowerCase('nb');const matches=articles.filter(a=>Object.values(a).join(' ').toLocaleLowerCase('nb').includes(term));$('#articles').innerHTML=matches.length?matches.map(a=>`<article class="article"><h2>${a.title}</h2><p>${a.text}</p><div class="helper"><strong>Fra hverdagen</strong><br>${a.example}</div><p><strong>En nyttig huskeregel:</strong> ${a.shortcut}</p><details><summary>Til deg som hjelper</summary><p>${a.parent}</p></details></article>`).join(''):'<p class="empty">Vi fant ingen forklaring. Prøv et kortere ord. Biblioteket dekker foreløpig seks grunnleggende temaer.</p>';};$('#search').oninput=filter;filter();}
function parent(){ $('#app').innerHTML=`<span class="eyebrow">ØV SAMMEN, MED RO OG NYSGJERRIGHET</span><h1>Hjelp til å finne neste steg.</h1><p>Spør «Hvordan tenkte du?» og gi tid til å svare. Bruk ting dere har hjemme, og ta pauser når det trengs.</p><div class="article"><h2>Dette har ${esc(state.name||'eleven')} øvd på</h2><p>Selvstendige svar er riktige førstesvar uten hint eller bildehjelp. Tallene er øvingshistorikk og dokumenterer ikke sikker mestring.</p>${MathEngine.topics.map(t=>`<p><strong>${t.title}</strong> — ${stat(t.id).independent} uten hjelp · ${stat(t.id).supported} med hjelp${stat(t.id).last?` · Sist øvd ${new Date(stat(t.id).last).toLocaleDateString('nb-NO')}`:''}</p>`).join('')}</div><div class="article"><h2>Et lite spørsmål kan åpne mye</h2><p>«Kan du vise det med klosser?»<br>«Finnes det en annen måte å finne svaret på?»<br>«Hvordan kan vi sjekke at det stemmer?»</p><button class="secondary" id="openLibrary">Se forklaringer og hverdagseksempler →</button></div><div class="article"><h2>Om denne førsteversjonen</h2><p>Mattesteg dekker foreløpig seks temaer i grunnleggende tallforståelse. Semesterprøver, flere elevprofiler og innhold for alle trinn kommer senere. Innholdet er en prototype og er ennå ikke prøvd ut med elever eller faglig kvalitetssikret av lærer.</p><p>Fornavn og fremgang lagres i nettleseren på denne enheten. Appen har én lokal elevprofil. Sletting av nettleserdata fjerner fremgangen. Opplesning bruker nettleserens talefunksjon.</p><a href="https://www.udir.no/lk20/mat01-05" target="_blank" rel="noopener">Læreplan i matematikk hos Udir ↗</a><p><button class="secondary" id="export">Last ned fremgangen</button> <button class="secondary" id="reset">Nullstill lokal profil</button></p><p id="dataMessage" aria-live="polite"></p></div>`;$('#openLibrary').onclick=()=>navigate('library');$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='mattesteg-fremgang.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};$('#reset').onclick=()=>{if(confirm('Vil du slette fornavn og all fremgang på denne enheten?')){state={name:'',avatar:'🦊',motion:false,progress:{},sessions:0};save();applyProfile();parent();$('#dataMessage').textContent='Den lokale profilen er nullstilt.';}};}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('.brand').onclick=e=>{e.preventDefault();navigate('home');};$('#profile').onclick=()=>{$('#name').value=state.name;document.querySelector(`input[name="avatar"][value="${state.avatar}"]`).checked=true;$('#motion').checked=state.motion;$('#profileDialog').showModal();};$('#closeDialog').onclick=()=>$('#profileDialog').close();$('#profileForm').onsubmit=e=>{e.preventDefault();state.name=$('#name').value.trim();state.avatar=document.querySelector('input[name="avatar"]:checked').value;state.motion=$('#motion').checked;save();applyProfile();$('#profileDialog').close();navigate('home');};applyProfile();navigate('home');
